import{_ as n,o as i,c as a,ag as t}from"./chunks/framework.CrXGS008.js";const h=JSON.parse('{"title":"Repair Station Business","description":"","frontmatter":{},"headers":[],"relativePath":"de/repair-station-business/index.md","filePath":"de/repair-station-business/index.md"}'),s={name:"de/repair-station-business/index.md"};function r(o,e,l,d,u,p){return i(),a("div",null,[...e[0]||(e[0]=[t(`<h1 id="repair-station-business" tabindex="-1">Repair Station Business <a class="header-anchor" href="#repair-station-business" aria-label="Permalink to &quot;Repair Station Business&quot;">​</a></h1><p>Das kostenpflichtige Add-on der <a href="/de/repair-station/">Repair Station</a>: Spieler kaufen Reparaturstationen, füllen sie mit Teilen auf, legen die Preise fest und leeren die Kasse. Alles wird über ein Tablet an der Station verwaltet, und jede Einstellung wird im Spiel bearbeitet.</p><h2 id="funktionen" tabindex="-1">Funktionen <a class="header-anchor" href="#funktionen" aria-label="Permalink to &quot;Funktionen&quot;">​</a></h2><ul><li><strong>Stationen zum Verkauf</strong>: Du wählst, welche Repair Stations gekauft werden können und zu welchem Preis. Siehe <a href="/de/repair-station-business/ownership">Besitz</a>.</li><li><strong>Tablet des Besitzers</strong>: Lager, Kasse, letzte Vorgänge, Preise, Name und Verkauf der Station an einem Ort.</li><li><strong>Teile</strong>: Jede Reparatur verbraucht Teile aus dem Lager der Station, gekauft mit dem Bankkonto oder als Gegenstände abgegeben. Siehe <a href="/de/repair-station-business/stock">Lager</a>.</li><li><strong>Preise des Besitzers</strong>: Jeder Besitzer legt einen Prozentsatz des Grundpreises fest, innerhalb der Grenzen, die du wählst, und von jeder Zahlung wird eine Steuer einbehalten.</li><li><strong>Faire Enden</strong>: Ein Besitzer, der verkauft, entfernt wird oder inaktiv ist, bekommt einen Teil des Kaufpreises plus die Kasse zurück, auch offline.</li><li><strong>Admin-Panel</strong>: Stationen zum Verkauf anbieten, den Preis ändern, das Lager setzen oder einen Besitzer entfernen, ohne das Spiel zu verlassen.</li><li><strong>HTTP-API und Webhooks</strong>: Stationen, Protokoll und Statistiken für deine Website sowie eine Discord-Nachricht bei jedem Kauf, Auffüllen, jeder Abhebung und jedem Stationsverlust. Siehe <a href="/de/repair-station-business/api">API und Webhooks</a>.</li><li><strong>Sechs Sprachen</strong>: Englisch, Französisch, Spanisch, Portugiesisch, Polnisch, Deutsch.</li></ul><h2 id="kompatibilitat" tabindex="-1">Kompatibilität <a class="header-anchor" href="#kompatibilitat" aria-label="Permalink to &quot;Kompatibilität&quot;">​</a></h2><ul><li>Frameworks: ESX Legacy, QBCore, QBox, ox_core, automatisch erkannt.</li><li>Abhängigkeiten: oxmysql, <code>nay_lib</code> und die <a href="/de/repair-station/">Repair Station</a> (<code>nay_repair</code>), im Kauf der Skripte enthalten.</li></ul><h2 id="installation" tabindex="-1">Installation <a class="header-anchor" href="#installation" aria-label="Permalink to &quot;Installation&quot;">​</a></h2><div class="language-cfg vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cfg</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ensure oxmysql</span></span>
<span class="line"><span>ensure nay_lib</span></span>
<span class="line"><span>ensure nay_repair</span></span>
<span class="line"><span>ensure nay_repair_business</span></span></code></pre></div><p>Alle Schritte stehen auf der Seite <a href="/de/getting-started">Erste Schritte</a>. Gib dir danach <code>nay_repair_business.config</code> (oder <code>nay.admin</code>) und öffne <code>/nay</code>, oder tippe <code>/nay:repairbusiness</code> für das Admin-Panel. Markiere im Panel die Stationen, die du verkaufen willst: Bis dahin verhalten sich die Stationen wie einfache Repair Stations.</p>`,9)])])}const f=n(s,[["render",r]]);export{h as __pageData,f as default};
